-- Replace every placeholder with the absolute Windows path to the generated CSV.
-- Run from a client started with --local-infile=1.  The files are generated by
-- `uv run freightflow transform`; do not hand-edit their codes or labels.
USE freightflow;

LOAD DATA LOCAL INFILE '<ABSOLUTE_PATH>/dim_zone.csv'
REPLACE INTO TABLE dim_zone
CHARACTER SET utf8mb4
FIELDS TERMINATED BY ',' ENCLOSED BY '"'
LINES TERMINATED BY '\n'
IGNORE 1 LINES
(zone_code, zone_name, @zone_long_description)
SET zone_type = 'Domestic';

LOAD DATA LOCAL INFILE '<ABSOLUTE_PATH>/dim_commodity.csv'
REPLACE INTO TABLE dim_commodity
CHARACTER SET utf8mb4
FIELDS TERMINATED BY ',' ENCLOSED BY '"'
LINES TERMINATED BY '\n'
IGNORE 1 LINES;

LOAD DATA LOCAL INFILE '<ABSOLUTE_PATH>/dim_mode.csv'
REPLACE INTO TABLE dim_mode
CHARACTER SET utf8mb4
FIELDS TERMINATED BY ',' ENCLOSED BY '"'
LINES TERMINATED BY '\n'
IGNORE 1 LINES;

LOAD DATA LOCAL INFILE '<ABSOLUTE_PATH>/dim_trade_type.csv'
REPLACE INTO TABLE dim_trade_type
CHARACTER SET utf8mb4
FIELDS TERMINATED BY ',' ENCLOSED BY '"'
LINES TERMINATED BY '\n'
IGNORE 1 LINES;

LOAD DATA LOCAL INFILE '<ABSOLUTE_PATH>/dim_year.csv'
REPLACE INTO TABLE dim_year
CHARACTER SET utf8mb4
FIELDS TERMINATED BY ',' ENCLOSED BY '"'
LINES TERMINATED BY '\n'
IGNORE 1 LINES;
